#!/usr/bin/env bash
set -euo pipefail
cd "$(dirname "$0")/.."

race=()
if [[ "${1:-}" == "--race" ]]; then
  race=(-race)
  shift
fi

probe_dir="$(mktemp -d)"
trap 'rm -rf "$probe_dir"' EXIT
go build "${race[@]}" -o "$probe_dir/attn" ./cmd/attn
env -u ATTN_CODEX_SHARED_PROFILE -u CODEX_THREAD_ID \
  ATTN_E2E_BIN="$probe_dir/attn" \
  go test "${race[@]}" -v -count=1 "$@" ./internal/daemon -run \
  '^(TestAStopReturningAfterReloadDoesNotRetireTheReloadedDriver|TestAnAutoSettleCountdownStandsDownWhileTheTurnsStopIsJudgedAndRearmsAfter|TestADoneVerdictOnAYieldedTurnSettlesItDespiteTheWorkStillRunning|TestAHaltRecordedBeforeTheSessionStartedDoesNotEndItsTurn|TestATurnIsJudgedOnceHoweverManyStopsReportIt|TestAVerdictLandingAfterAnApprovalLeavesTheApprovalStanding|TestAParkedVerdictHoldsAYieldedTurnWorkingPastTheIdlePromptUntilItExpires|TestAPendingMetadataReplyDoesNotBlockTheDriversReloadResponse|TestAStaleLaunchCompletionLeavesTheNewerReloadsReportsQueued|TestAConversationReportedDuringLaunchSurvivesTheRunsImmediateExit|TestAMissingBoundTranscriptNeverUsesANeighborsReply|TestRecreatingAWorktreeChecksPluginStorageAfterProjectSettingsReturn|TestAGardenReviewWaitsForAStalledResumeDriverOnlyOncePerCapture|TestAGardenReviewInspectsSharedPluginStorageOncePerCapture|TestInputFindsItsConversationWhenBindingFinishesDuringLookup|TestASharedCodexTerminalShowsTheSessionOfEachConversationItMovesToBeforeAnyPrompt|TestResumeToARecoverableSessionsConversationMovesItIntoThePane|TestAPlainCodexThatResumesAHiddenSharedConversationShowsThatSessionAsPlain|TestASnoozeStillWakesAfterTakingOverALiveConversation|TestAResumedConversationCountsOnlyTheUsageAfterTheResume|TestAResumedSharedConversationsRunSurvivesItsOutcome|TestReloadingOneSharedTerminalKeepsTheOthersPendingConversation|TestAnEndedRuntimeCannotReplayItsPendingConversationOverItsReplacement|TestConversationMovesBeforeAnOutcomeEachGetASessionAndTheirOwnCost|TestAConversationMoveCommittedBeforeACrashReceivesItsOutcomeAfterRestart|TestAReloadDropsThePendingConversationOfTheRuntimeItReplaced|TestARefusedConversationMoveLeavesTheTerminalOnItsSession|TestAConversationReportRetriesAfterStorageRecovers|TestAnExitBeforeAConversationOutcomeEndsTheCommittedConversation|TestADroppedConversationMoveKeepsItsInFlightDeliveryUsable|TestAnAppliedObservationIsNotReplayedOverALaterHomeBinding|TestACandidatesTitleAndTurnSurviveItsOutcome|TestACandidatesFailedTitleCanBeRetriedAfterRestart|TestANewChatsSubmitSurvivesThePreviousClassifiersLateIdle|TestClearOpensANewSessionInTheSameTerminalAndClosesTheOldOneWhole|TestResumeToAClosedSessionsConversationReopensItInThePane|TestCodexNewOpensANewSessionOnTheNewChatsFirstPrompt|TestAConversationMoveSavedJustBeforeACrashIsDecidedAfterTheRestart|TestClaudeSessionsShowTheirConversationIsSharedWhileBothProcessesRunIt|TestTwoTerminalsShowOneSharedCodexSessionUntilTheLastTileClosesAndArchivesIt|TestOnlyAPromptTheHarnessMarksSubmittedCountsAsTheUsersTurn|TestTheUsersPromptArmsAutoSettleWhenTheHarnessReportsWorkingBeforeItsSubmitHook|TestAnApprovalKeypressEarnsNoCreditAndHoldsAttnsDoorbellForTheQuietWindow)$'
